def prepare_geometries():
    from tools.glm_perf.reconstruction_native import DECODE_ROWS, GLM_GEOMETRIES, ProjectionGeometry

    shapes = ((128, 256), (256, 512), *GLM_GEOMETRIES)
    return tuple(
        ProjectionGeometry(rows, experts, n, k) for experts in (3, 72) for n, k in shapes for rows in DECODE_ROWS
    )

def prepare():
    import importlib, hashlib
    from pathlib import Path
    helpers = {'tools.glm_perf.glm_int4': 'c231d055f1f701f396636ab982adc63da03e155c6dcdd44a03f7979d941e8af7', 'tools.glm_perf.reconstruction_native': 'ea128543c4cfeaf3ca7c8b040152446abb4cef1bc4d99dbd50b6952d4eb751a9', 'tools.glm_perf.reconstruction_probe': '64b40634adcf237ce2f043e68317dca66090bfcba1a4a5a0ac08d1aa0ef104db', 'tools.glm_perf.resident_candidates.expert_reconstruction': 'c225ed51a9fffef0659ae621b2405cdd9ff3884493c0875ae8c3908974cbf15d'}
    for name, expected in helpers.items():
        module = importlib.import_module(name)
        if hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest() != expected:
            raise ValueError('worker helper differs from manifest: ' + name)
    from tools.glm_perf.glm_int4 import NativeW4Projection
    root = Path('/home/matteius/experiments/glm-reconstruction-20261006/build-w3-v2')
    resources = {'w4a8': NativeW4Projection(root / 'glm_w4a8_pack.bin', root / 'glm_w4a8_matmul.bin', prepare_geometries())}
    from tools.glm_perf.reconstruction_native import ReconstructionProjection, PROFILES
    for profile in PROFILES:
        resources[profile] = ReconstructionProjection(root / 'reconstruction_kernel.bin', profile, prepare_geometries())
    return resources

def validate(resources):
    from tools.glm_perf.reconstruction_probe import component_cases, gate_case, graph_gate
    records = [gate_case(resources['w4a8'], geometry, repeats=2) for geometry in component_cases()]
    graph_gate(resources['w4a8'], component_cases()[2])
    import torch
    from tools.glm_perf.reconstruction_probe import w3_gate
    projections = {p: resources[p] for p in ('gm', 'l1', 'l1_singleton')}
    for geometry in component_cases():
        w3_gate(projections, geometry, torch.ops._C_ascend.npu_w2_grouped_blocked_dequant_matmul_310, 2)
    for projection in projections.values():
        graph_gate(projection, component_cases()[2], 3, torch.ops._C_ascend.npu_w2_grouped_blocked_dequant_matmul_310)
    return {'passed': True, 'cases': len(records), 'weight_format': 'unchanged_signed_block32', 'activation_format': 'new_group32_int8', 'model_quality': 'not_evaluated'}
